INSERT INTO vocabulary_card_source (
    source_uid, card_uid, user_id, source_type, source_ref, source_title,
    source_url, context_text, raw_term, idempotency_key, captured_at, metadata_json
) VALUES (
    #{sourceUid}, #{cardUid}, #{userId}, #{sourceType}, #{sourceRef}, #{sourceTitle},
    #{sourceUrl}, #{contextText}, #{rawTerm}, #{idempotencyKey}, #{capturedAt}, #{metadataJson}
)

mapper.select:
SELECT 
FROM vocabulary_card_source
WHERE user_id = #{userId}
  AND idempotency_key = #{idempotencyKey}
LIMIT 1

SELECT source.card_uid, source.user_id, source.source_type, SUM(COUNT(*)) OVER (PARTITION BY source.card_uid) AS source_count FROM vocabulary_card_source source INNER JOIN vocabulary_card card ON card.card_uid = source.card_uid AND card.user_id = #{userId} AND card.deleted_at IS NULL WHERE source.user_id = #{userId} AND source.card_uid IN
#{cardUid}
GROUP BY source.card_uid, source.user_id, source.source_type ORDER BY source.card_uid, source.source_type
